// @vitest-environment node
/**
 * Golden URLs: `__fixtures__/image-golden.jsonl` was generated by running v8
 * storefronts' own image helpers, unchanged (the vendored v7
 * `getOptimizedMediaUrl` / `getSrcSet` copies, two next/image loaders and a
 * fixed-frame catalog loader), over VTEX sources (catalog and file-manager
 * URLs, on VTEX hosts and on others). Each config below is the
 * `createImageUrl` a site builds from these providers and `decoCdn`, and must
 * reproduce its URLs byte for byte: no case changes. A helper that throws
 * today on a source is recorded as "<throws>" and must still throw.
 */
import { readFileSync } from "node:fs";
import {
  createImageUrl,
  decoCdn,
  type ImageUrl,
  type ResizeOptions,
  srcSet,
} from "@decocms/blocks/image";
import { describe, expect, it } from "vitest";
import { vtexCatalog, vtexCatalogFrame, vtexCatalogWebp, vtexFileManager } from "./image.ts";

interface Case {
  config: string;
  call: "url" | "srcSet" | "isOptimizable";
  src: string;
  opts?: ResizeOptions & { widths?: number[]; factors?: number[] };
  frame?: [number, number];
  expected: string | boolean | null;
}

const cases: Case[] = readFileSync(
  new URL("./__fixtures__/image-golden.jsonl", import.meta.url),
  "utf-8",
)
  .split("\n")
  .filter(Boolean)
  .map((line) => JSON.parse(line));

/** v7's TanStack Image: VTEX natively, everything else through the Deco CDN. */
const tanstack = (cdn: Parameters<typeof decoCdn>[0] = {}) =>
  createImageUrl({ providers: [vtexCatalog(), decoCdn({ sources: "all", ...cdn })] });

/** The next/image loaders: catalog as WebP, file manager, then the Deco CDN at "high". */
const nextLoader = (via: "query" | "thumbor") =>
  createImageUrl({
    providers: [
      vtexCatalogWebp(),
      vtexFileManager({ via }),
      decoCdn({ quality: "high", fit: "contain", layout: "quality-last" }),
    ],
  });

const CONFIGS: Record<string, (c: Case) => ImageUrl> = {
  "tanstack-decoims-high": () => tanstack({ domain: "decoims.com", quality: "high" }),
  "tanstack-default": () => tanstack(),
  "tanstack-anchored": () => tanstack({ stripAssetHosts: "leading" }),
  "next-thumbor": () => nextLoader("thumbor"),
  "next-query": () => nextLoader("query"),
  "next-catalog-frame": (c) => {
    const [width, height] = c.frame as [number, number];
    return createImageUrl({ providers: [vtexCatalogFrame({ frame: { width, height } })] });
  },
  "next-catalog-exact": () => createImageUrl({ providers: [vtexCatalogFrame()] }),
};

function run(c: Case): string | boolean | null {
  const url = CONFIGS[c.config](c);
  try {
    if (c.call === "isOptimizable") return url.isOptimizable(c.src);
    if (c.call === "srcSet") return srcSet(url, c.src, c.opts ?? {}) ?? null;
    return url(c.src, c.opts as ResizeOptions);
  } catch {
    return "<throws>";
  }
}

describe("golden URLs: each storefront's current helpers, byte for byte", () => {
  it("covers every config, and no case is a changed URL", () => {
    expect(new Set(cases.map((c) => c.config))).toEqual(new Set(Object.keys(CONFIGS)));
    expect(cases.filter((c) => "before" in c)).toEqual([]);
  });

  for (const config of Object.keys(CONFIGS)) {
    it(config, () => {
      const mine = cases.filter((c) => c.config === config);
      expect(mine.length).toBeGreaterThan(0);
      const diffs = mine
        .map((c) => ({ c, got: run(c) }))
        .filter(({ c, got }) => got !== c.expected)
        .map(({ c, got }) => ({
          call: c.call,
          src: c.src,
          opts: c.opts,
          expected: c.expected,
          got,
        }));
      expect(diffs).toEqual([]);
    });
  }
});

describe("VTEX providers", () => {
  it("vtexCatalog: VTEX hosts only, {id}-{w}-{h ?? w}", () => {
    const u = createImageUrl({ providers: [vtexCatalog()] });
    expect(u("https://s.vtexassets.com/arquivos/ids/1-500-500/a.jpg?v=1", { width: 300 })).toBe(
      "https://s.vtexassets.com/arquivos/ids/1-300-300/a.jpg?v=1",
    );
    expect(u.isOptimizable("https://www.example.com/arquivos/ids/1/a.jpg")).toBe(false);
  });

  it("vtexCatalogFrame: any host, a fixed frame or the call's box, rounded", () => {
    const own = "https://www.example.com/arquivos/ids/1/a.jpg";
    expect(
      createImageUrl({ providers: [vtexCatalogFrame({ frame: { width: 4, height: 5 } })] })(own, {
        width: 401,
      }),
    ).toBe("https://www.example.com/arquivos/ids/1-401-501/a.jpg");
    expect(createImageUrl({ providers: [vtexCatalogFrame()] })(own, { width: 10.4 })).toBe(
      "https://www.example.com/arquivos/ids/1-10-10/a.jpg",
    );
  });

  it("vtexCatalogWebp: auto height, .webp, quality on VTEX's 1-10 scale, the query kept", () => {
    const u = createImageUrl({ providers: [vtexCatalogWebp()] });
    const src = "https://s.vtexassets.com/arquivos/ids/1/a.jpg?v=1";
    expect(u(src, { width: 828 })).toBe(
      "https://s.vtexassets.com/arquivos/ids/1-828-auto/a.webp?v=1&quality=8",
    );
    expect(u(src, { width: 828, quality: 75 })).toContain("quality=8");
    expect(u(src, { width: 828, quality: "original" })).toContain("quality=10");
  });

  it("vtexFileManager: Thumbor for raster files, SVG and GIF raw, or the query resizer", () => {
    const asset = "https://s.vtexassets.com/assets/vtex.file-manager-graphql/images/a___b.png";
    const thumbor = createImageUrl({ providers: [vtexFileManager({ via: "thumbor" })] });
    expect(thumbor(asset, { width: 640 })).toBe(
      `https://s.vtexassets.com/unsafe/640x0/filters:no_upscale():quality(80):format(webp)/${encodeURIComponent(asset)}`,
    );
    expect(thumbor(asset.replace(".png", ".svg"), { width: 640 })).toBe(
      asset.replace(".png", ".svg"),
    );
    const query = createImageUrl({ providers: [vtexFileManager({ via: "query" })] });
    expect(query(asset, { width: 640 })).toBe(`${asset}?width=640&aspect=true&quality=8`);
  });
});

describe("the ./image subpath", () => {
  it("package.json maps it to the source and the build", () => {
    const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf-8"));
    expect(pkg.exports["./image"]).toEqual({
      types: "./dist/image.d.ts",
      source: "./src/image.ts",
      default: "./dist/image.js",
    });
  });

  it("exports exactly the documented runtime names", async () => {
    expect(Object.keys(await import("./image.ts")).sort()).toEqual([
      "vtexCatalog",
      "vtexCatalogFrame",
      "vtexCatalogWebp",
      "vtexFileManager",
    ]);
  });
});
